import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.DYd_c05j.js";const u=JSON.parse('{"title":"External Sentinel contract v1","description":"","frontmatter":{},"headers":[],"relativePath":"sentinel-contract-v1.md","filePath":"sentinel-contract-v1.md","lastUpdated":null}'),s={name:"sentinel-contract-v1.md"};function o(r,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="external-sentinel-contract-v1" tabindex="-1">External Sentinel contract v1 <a class="header-anchor" href="#external-sentinel-contract-v1" aria-label="Permalink to &quot;External Sentinel contract v1&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Sentinel is a standalone availability observer. It has no Homelab Console database, MCP identity, provider credentials or remediation capability. Runtime targets come only from its startup configuration. The optional home-side client or API-lifecycle worker sends a heartbeat; the core API never calls Sentinel in response to a user, tool, model or MCP request.</p><h2 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h2><h3 id="get-health" tabindex="-1"><code>GET /health</code> <a class="header-anchor" href="#get-health" aria-label="Permalink to &quot;`GET /health`&quot;">​</a></h3><p>Returns <code>200 application/json</code>:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This is process liveness only. It does not guarantee Telegram delivery, target health, SQLite writability or recent heartbeats. Other GET paths return <code>404</code>.</p><h3 id="post-heartbeat-source-id" tabindex="-1"><code>POST /heartbeat/{source_id}</code> <a class="header-anchor" href="#post-heartbeat-source-id" aria-label="Permalink to &quot;`POST /heartbeat/{source_id}`&quot;">​</a></h3><p>Authentication accepts either:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;token&gt;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">X-Sentinel-Token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;token&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The configured token must be non-empty and comparison is constant-time. Missing or invalid authentication returns:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">401 {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;unauthorized&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>source_id</code> is percent-decoded and trimmed; an empty value returns <code>400 {&quot;ok&quot;:false,&quot;error&quot;:&quot;missing_source_id&quot;}</code>. The optional JSON object is bounded to the first 4096 bytes and stored only as heartbeat evidence. For v1, an empty, malformed or non-object body is treated as <code>{}</code>. Receipt updates the source timestamp and returns <code>200 {&quot;ok&quot;:true}</code>. Other POST paths return <code>404</code>.</p><p>The client payload currently contains informational <code>source</code>, <code>sent_at</code>, <code>host</code> and <code>platform</code> fields. Server health decisions depend on authenticated receipt, not on caller-provided field values.</p><h2 id="configuration-and-monitoring-semantics" tabindex="-1">Configuration and monitoring semantics <a class="header-anchor" href="#configuration-and-monitoring-semantics" aria-label="Permalink to &quot;Configuration and monitoring semantics&quot;">​</a></h2><p>The JSON configuration owns all HTTP targets, heartbeat source ids, expected status ranges, timeouts, confirmation counts, notification groups, aggregation and cooldown values. Requests cannot add targets or URLs. Secrets are supplied only through runtime environment variables:</p><ul><li><code>SENTINEL_HEARTBEAT_TOKEN</code>;</li><li><code>TELEGRAM_BOT_TOKEN</code>;</li><li><code>TELEGRAM_ALLOWED_CHAT_ID</code>.</li></ul><p>Environment also selects the config path, SQLite state path and listen host/port. Port <code>8766</code> is the v1 deployment default.</p><p>Incidents are deduplicated as <code>http:{target_id}</code> and <code>heartbeat:{source_id}</code>. States are <code>pending</code>, <code>open</code> and <code>resolved</code>; recovery requires the configured healthy observation streak. Notification delivery failure must not stop monitoring.</p><h2 id="persistence-and-deployment" tabindex="-1">Persistence and deployment <a class="header-anchor" href="#persistence-and-deployment" aria-label="Permalink to &quot;Persistence and deployment&quot;">​</a></h2><p>SQLite state is local to Sentinel and must live on a persistent volume. Upgrade and rollback preserve the database and dedupe keys. Schema changes within v1 must be additive. The container runs non-root, mounts configuration read-only and uses <code>GET /health</code> as its Docker healthcheck.</p><h2 id="compatibility-and-conformance" tabindex="-1">Compatibility and conformance <a class="header-anchor" href="#compatibility-and-conformance" aria-label="Permalink to &quot;Compatibility and conformance&quot;">​</a></h2><p>Compatible v1 implementations must pass tests for authentication, body bounds, heartbeat persistence, restart persistence, failure/recovery confirmation, group aggregation, notification failure and v1 client/server interoperability. A breaking endpoint, authentication, dedupe or persistence change requires v2.</p>',24)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
